style:
/* 旗墨 —— 顶部 RESUME 旗标，藏青标牌标题压在细线上 */

.tw-qimo.layout-band.resume-paper .paper-flow::before {
  content: "RESUME";
  display: block;
  width: 36mm;
  margin: 0 auto 7mm;
  padding: 1.6mm 0;
  background: var(--paper-accent);
  clip-path: polygon(3.4mm 0, 100% 0, calc(100% - 3.4mm) 100%, 0 100%);
  color: #fff;
  font-size: calc(var(--paper-base-size) * 1.14);
  font-weight: 700;
  letter-spacing: 0.34em;
  text-align: center;
  text-indent: 0.34em;
  print-color-adjust: exact;
}

.tw-qimo.layout-band.resume-paper .paper-header {
  margin-bottom: 6.5mm;
  padding-bottom: 4.4mm;
  border-bottom: 0.3mm solid #d8dfe8;
}

.tw-qimo.layout-band.resume-paper .paper-header--photo {
  align-items: flex-start;
  gap: 8mm;
}

.tw-qimo.layout-band.resume-paper .paper-header__main {
  flex: 1 1 auto;
  min-width: 0;
}

.tw-qimo.layout-band.resume-paper .paper-photo {
  order: 3;
  width: 24mm;
  height: 33mm;
  border: 0.4mm solid #dde3ea;
  border-radius: 0;
  box-shadow: none;
}

.tw-qimo.layout-band.resume-paper .paper-photo--monogram {
  display: grid;
  place-items: center;
  background: #eef1f6;
  color: var(--paper-accent);
  font-size: calc(var(--paper-base-size) * 2);
  font-weight: 700;
}

.tw-qimo.layout-band.resume-paper .paper-name {
  color: #182430;
  font-family: var(--paper-font-family);
  font-size: calc(var(--paper-base-size) * 2.3);
  letter-spacing: 0.08em;
}

.tw-qimo.layout-band.resume-paper .paper-identity {
  padding: 0;
  border: none;
  color: #66757f;
  font-size: calc(var(--paper-base-size) * 0.84);
}

.tw-qimo.layout-band.resume-paper .paper-role {
  margin-top: 1.8mm;
  color: #33424f;
  font-size: calc(var(--paper-base-size) * 0.96);
  font-weight: 400;
}

.tw-qimo.layout-band.resume-paper .paper-contacts {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 1.4mm 8mm;
  margin-top: 3.2mm;
  color: #33424f;
  font-size: calc(var(--paper-base-size) * 0.87);
}

.tw-qimo.layout-band.resume-paper .paper-contact {
  display: flex;
  gap: 1.8mm;
}

.tw-qimo.layout-band.resume-paper .paper-contact + .paper-contact::before {
  display: none;
}

.tw-qimo.layout-band.resume-paper .paper-contact__label {
  flex: 0 0 auto;
  color: #7a8894;
}

/* 标题：旗标贴齐正文左缘，后面拖一条细线 */
.tw-qimo.layout-band.resume-paper .paper-style-flag .paper-section__title {
  margin-left: 0;
  margin-bottom: 4mm;
}

.tw-qimo.layout-band.resume-paper .paper-section__body {
  color: #2f3d49;
}

.tw-qimo.layout-band.resume-paper .paper-item-title {
  color: #17222d;
}

.tw-qimo.layout-band.resume-paper .paper-item-period {
  color: #77848f;
  font-size: calc(var(--paper-base-size) * 0.86);
}

.tw-qimo.layout-band.resume-paper .paper-item-sub {
  color: #44525f;
}

.tw-qimo.layout-band.resume-paper .paper-rich ul,
.tw-qimo.layout-band.resume-paper .paper-rich ol {
  margin-top: 0.8mm;
  padding-left: 0;
  list-style: none;
}

.tw-qimo.layout-band.resume-paper .paper-rich li {
  position: relative;
  margin: 0.7mm 0;
  padding-left: 3.6mm;
}

.tw-qimo.layout-band.resume-paper .paper-rich li::before {
  content: "";
  position: absolute;
  top: 0.7em;
  left: 0.4mm;
  width: 1.1mm;
  height: 1.1mm;
  border-radius: 50%;
  background: #93a0ac;
  print-color-adjust: exact;
}

.tw-qimo.layout-band.resume-paper .paper-note__tag {
  color: #17222d;
  font-weight: 600;
}

.tw-qimo.layout-band.resume-paper .paper-footer {
  border-top: 0.2mm solid #e2e7ee;
  color: #9ba7b3;
}
